BEGIN IMMEDIATE;
CREATE TABLE IF NOT EXISTS scans(id INTEGER PRIMARY KEY,root BLOB NOT NULL,started INTEGER NOT NULL,ended INTEGER,state TEXT NOT NULL,mode TEXT NOT NULL,report TEXT,capacity INTEGER,available INTEGER,sampled INTEGER);
CREATE TABLE IF NOT EXISTS entries(scan_id INTEGER NOT NULL REFERENCES scans(id) ON DELETE CASCADE,path BLOB NOT NULL,parent BLOB NOT NULL,kind TEXT NOT NULL,identity TEXT NOT NULL,apparent INTEGER NOT NULL,allocated INTEGER NOT NULL,links INTEGER NOT NULL,modified_ns INTEGER NOT NULL,changed_ns INTEGER NOT NULL,excluded TEXT,PRIMARY KEY(scan_id,path));
CREATE INDEX IF NOT EXISTS entry_identity ON entries(scan_id,identity);
CREATE INDEX IF NOT EXISTS entry_size ON entries(scan_id,allocated DESC);
CREATE TABLE IF NOT EXISTS active(singleton INTEGER PRIMARY KEY CHECK(singleton=1),scan_id INTEGER NOT NULL REFERENCES scans(id));
CREATE TABLE IF NOT EXISTS jobs(id INTEGER PRIMARY KEY,path BLOB NOT NULL,identity TEXT NOT NULL UNIQUE,state TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS issues(scan_id INTEGER NOT NULL REFERENCES scans(id) ON DELETE CASCADE,path BLOB NOT NULL,reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value BLOB NOT NULL);
PRAGMA user_version=1;
COMMIT;
